import{_ as r,a0 as l,w as p,s,I as a,x as e,a1 as o,A as i,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const N=JSON.parse('{"title":"使用 GNOME 在 Fedora 中启用分数缩放 | LCTT x X-CMD","titleTemplate":false,"description":"使用 GNOME 在 Fedora 中启用分数缩放 | LCTT (202306) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 GNOME 在 Fedora 中启用分数缩放 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 GNOME 在 Fedora 中启用分数缩放 | LCTT (202306) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202306/20230529.0 ⭐️⭐️ Enable Fractional Scaling in Fedora with GNOME","title":"使用 GNOME 在 Fedora 中启用分数缩放","tag":"202306","desc":""},"relativePath":"202306/20230529.0 ⭐️⭐️ Enable Fractional Scaling in Fedora with GNOME.md","filePath":"[post].md"}'),u={name:"202306/20230529.0 ⭐️⭐️ Enable Fractional Scaling in Fedora with GNOME.md"};function g(m,t,f,b,w,F){const n=l("Link");return p(),s("div",null,[t[18]||(t[18]=a("h1",{id:"使用-gnome-在-fedora-中启用分数缩放",tabindex:"-1"},[e("使用 GNOME 在 Fedora 中启用分数缩放 "),a("a",{class:"header-anchor",href:"#使用-gnome-在-fedora-中启用分数缩放","aria-label":"Permalink to “使用 GNOME 在 Fedora 中启用分数缩放”"},"​")],-1)),t[19]||(t[19]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202306/27/155914j288s2lh4ovkx6jk.jpg",alt:""})],-1)),t[20]||(t[20]=a("blockquote",null,[a("p",null,"以下是在 GNOME 版本的 Fedora 工作站中启用分数缩放的步骤。")],-1)),a("p",null,[a("ruby",null,[o(n,{href:"https://wiki.gnome.org/Initiatives/FracionalScaling"},{default:i(()=>[...t[0]||(t[0]=[e("分数缩放",-1)])]),_:1}),t[1]||(t[1]=a("rt",null,"Fractional Scaling",-1))]),t[2]||(t[2]=e(" 是一项方便的功能，可让你最大程度地优化 HiDPI 显示器和高分辨率笔记本电脑。通过微调缩放比例，你可以创建平衡良好、既不太大也不太小且美观的桌面显示。虽然通过分辨率设置也可以，但由于操作系统的限制，它们通常符合你的实际情况。",-1))]),t[21]||(t[21]=d('<p>此外，它还允许你增加显示屏上文本和其他 UI 元素的大小，而不会使所有内容显得模糊。如果你有高分辨率显示器并希望使文本更易于阅读，这将很有用。</p><p>Ubuntu 20.04 LTS 在 2020 年引入了 100%、125%、150%、175% 和 200% 的分数缩放。它可以在“<ruby>显示<rt>Display</rt></ruby>”页面下的“<ruby>设置<rt>Settings</rt></ruby>”中找到。</p><p>但在默认 GNOME 桌面的 Fedora 工作站中，只有 100% 和 200% 缩放可用。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/05/Default-Scaling-in-GNOME-in-Fedora.jpg" alt="Fedora 中 GNOME 的默认缩放"></p><h3 id="如何使用-gnome-在-fedora-中启用分数缩放" tabindex="-1">如何使用 GNOME 在 Fedora 中启用分数缩放 <a class="header-anchor" href="#如何使用-gnome-在-fedora-中启用分数缩放" aria-label="Permalink to “如何使用 GNOME 在 Fedora 中启用分数缩放”">​</a></h3><p>打开终端窗口（<code>CTRL+ALT+T</code>）。</p><p>运行以下命令。此命令在带有 GNOME 的 Fedora 中启用 125%、150% 和 175% 缩放因子。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gsettings set org.gnome.mutter experimental-features &quot;[&#39;scale-monitor-framebuffer&#39;]&quot;</span></span></code></pre></div><p>重启 Fedora。</p><p>打开 “设置” 应用，你应该会看到新的缩放因子。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/05/Fractional-Scaling-in-Fedora-with-GNOME.jpg" alt="在 GNOME Fedora 中进行分数缩放"></p><p>但是，重要的是要注意分数缩放并不总是完美的。某些应用程序可能无法正确缩放。例如，如果应用程序设计不当，非 GTK 应用可能看起来很模糊。</p><p>此外，请务必注意，由于 GPU 的渲染工作量更大，分数缩放可能会增加笔记本电脑的功耗。</p><h3 id="一些使用说明" tabindex="-1">一些使用说明 <a class="header-anchor" href="#一些使用说明" aria-label="Permalink to “一些使用说明”">​</a></h3><p>根据我的测试，上述命令在 Wayland 中应该是有效的。</p><p>如果你不想使用上述命令，但仍想获得类似的体验，那么你可以按照以下步骤操作：</p><p>使用 <code>sudo dnf install gnome-tweaks</code> 安装 GNOME “<ruby>调整<rt>Tweaks</rt></ruby>” 应用。</p><p>转到 “<ruby>字体<rt>Fonts</rt></ruby>” 设置并更改比例因子。</p><p>示例：如果你想保持 100% 缩放比例但想要更大的字体，请尝试缩放比例设为 1.1 或 1.2。根据你的需要进行调整。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/05/Font-scaling.jpg" alt="字体缩放"></p><ul><li>125%：这是分数缩放的典型值。它将文本大小和 UI 元素增加 25% 而不会使所有内容显得模糊。</li><li>150%：对于想要放大文本和其他 UI 元素但又不想增加显示分辨率的人来说，这是一个很好的值。</li><li>175%：对于想要使文本和其他 UI 元素变得非常大的人来说，这是一个很好的值。</li></ul><p>尝试不同的缩放因子对于找到最适合你的缩放因子至关重要。最佳缩放因子将取决于你的显示器尺寸、视力和偏好。</p><p>我希望本指南有所帮助。</p><p><em>（题图：MJ/4346b556-57ed-4c76-b2c9-e651e0d229f5）</em></p><hr>',25)),a("p",null,[t[4]||(t[4]=e("via: ",-1)),o(n,{href:"https://www.debugpoint.com/fractional-scaling-fedora/"},{default:i(()=>[...t[3]||(t[3]=[e("https://www.debugpoint.com/fractional-scaling-fedora/",-1)])]),_:1})]),a("p",null,[t[9]||(t[9]=e("作者：",-1)),o(n,{href:"https://www.debugpoint.com/author/admin1/"},{default:i(()=>[...t[5]||(t[5]=[e("Arindam",-1)])]),_:1}),t[10]||(t[10]=e(" 选题：",-1)),o(n,{href:"https://github.com/lkxed/"},{default:i(()=>[...t[6]||(t[6]=[e("lkxed",-1)])]),_:1}),t[11]||(t[11]=e(" 译者：",-1)),o(n,{href:"https://github.com/geekpi"},{default:i(()=>[...t[7]||(t[7]=[e("geekpi",-1)])]),_:1}),t[12]||(t[12]=e(" 校对：",-1)),o(n,{href:"https://github.com/wxy"},{default:i(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[15]||(t[15]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原创编译，",-1)),o(n,{href:"https://linux.cn/"},{default:i(()=>[...t[14]||(t[14]=[e("Linux中国",-1)])]),_:1}),t[17]||(t[17]=e(" 荣誉推出",-1))])])}const k=r(u,[["render",g]]);export{N as __pageData,k as default};
